selected.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [row['id'] for row in group]
        if valid(ids):
            result = ids
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if not valid(current):
        status('report')
else:
    if valid(result):
        write('/output/selection', result)
        current = read('/output/selection')
        if current == result:
            state = receipt('report')
            if state == 'unattempted' or state == 'failure':
                send('report', 'team', current)
            elif state == 'unknown':
                status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')
